import React, { useState } from 'react';
import './StartProject.css'; // Make sure this CSS file exists

const StartProject = () => {
  const [projectName, setProjectName] = useState('');
  const [projectDescription, setProjectDescription] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    if (projectName && projectDescription) {
      alert(`🚀 Project "${projectName}" created successfully!`);
      setProjectName('');
      setProjectDescription('');
    }
  };

  return (
    <section className="start-project-section">
      <div className="start-project-container">
        <h2 className="start-project-heading">🚀 Launch Your Open Source Project</h2>
        <form onSubmit={handleSubmit} className="start-project-form">
          <label>
            Project Name:
            <input
              type="text"
              placeholder="Enter your project name"
              value={projectName}
              onChange={(e) => setProjectName(e.target.value)}
              required
            />
          </label>
          <label>
            Project Description:
            <textarea
              placeholder="Describe your project idea..."
              value={projectDescription}
              onChange={(e) => setProjectDescription(e.target.value)}
              required
            />
          </label>
          <button type="submit">Create Project</button>
        </form>
      </div>
    </section>
  );
};

export default StartProject;
